questionvariables.text:
scenario:rand(2);
ta1:if scenario=0 then 2 else 3;
options1:random_permutation([
[1,false,"Repeat the same irrigation trial without changing its objective"],
[2,is(scenario=0),"Use the existing climate series with an appropriately validated crop model"],
[3,is(scenario=1),"Conduct exploratory discussions with farmers to identify their priorities"],
[4,false,"Choose the most elaborate experimental layout before deciding what to learn"]
]);
